import csv, collections
rows=list(csv.DictReader(open('family_prsm_rows.csv')))
def shift(r):
    s=r['unexpected_mods'].split(':')[0]
    return float(s) if s else None
def form(r): return r['n_terminal_form']
sel=[r for r in rows if shift(r) is not None]
print('rows',len(sel))
# group by protein and mass level
for prot in ('C6T4V4','Q2KMJ4'):
    sub=[r for r in sel if prot in r['accession']]
    bymass=collections.defaultdict(list)
    for r in sub: bymass[round(float(r['adjusted_precursor_mass']),2)].append(r)
    print(f"\n== {prot}: {len(sub)} rows, {len(bymass)} distinct precursor-mass levels")
    pairs=0
    for m,rs in sorted(bymass.items()):
        forms={form(r):shift(r) for r in rs}
        if 'NONE' in forms and 'NME' in forms:
            pairs+=1
            if pairs<=6:
                print(f"  M={m:9.2f}  NONE shift={forms['NONE']:+.3f}  NME shift={forms['NME']:+.3f}  diff={forms['NME']-forms['NONE']:+.3f}")
    print(f"  levels carrying BOTH terminal forms: {pairs}")
    # distribution of residual difference
    diffs=[]
    for m,rs in bymass.items():
        forms={form(r):shift(r) for r in rs}
        if 'NONE' in forms and 'NME' in forms: diffs.append(round(forms['NME']-forms['NONE'],3))
    print('  diffs',collections.Counter(diffs).most_common(6))
